using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.Profiling;
namespace MassiveArmy.Planetary {
    [DefaultExecutionOrder(-230)]public sealed class SettlementAiSupplyValidation:MonoBehaviour {
        // Dispatch counters prove that the live audit exercised reused failed searches.
        [Serializable]sealed class TeamReport {public int population,housing,employed,jobs,midpointBuildings,midpointPopulation,outposts,frontierDeposits;public int maximumMines,totalMines,connectedMines,buildings,cargo;public float endingMaterials;public double longestMaterialDrought,deliveredMaterials;public bool recovered;public int satellites,researchStations,launchPads;public string[] technologies;public double food,seeds,grain,foodDemand,foodSupplied;public string activity;public List<string> installations=new List<string>(),trucks=new List<string>();}
        [Serializable]sealed class Report {public string status="PASS",error="",measurement="Actual autonomous AI, 900 simulation seconds; wall frame intervals, no CPU army mirror or wallet grants";public List<string> checks=new List<string>();public TeamReport[] teams={new TeamReport(),new TeamReport()};public int units,width,height,runtimeErrors;public double economySeconds;public double medianMs,p95Ms,simulationHz;public long allocatedBytes,reservedBytes,dispatchFailureReuses,dispatchAuditRechecks;public double[] frameSamplesMs;}
        readonly Report report=new Report();readonly List<double> frames=new List<double>();readonly double[] drought=new double[2];readonly bool[] depleted=new bool[2];PlanetDevelopment world;string output;double started,previous;uint firstTick;int duration=900;uint lastHour,previousAuditTick;int[] midpointBuildings=new int[2],midpointPopulation=new int[2];
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){if(!Application.isEditor&&Array.IndexOf(Environment.GetCommandLineArgs(),"-planet-economy-ai-validation")>=0)new GameObject("Autonomous settlement supply validation").AddComponent<SettlementAiSupplyValidation>();}
        void Awake(){var args=Environment.GetCommandLineArgs();int durationArg=Array.IndexOf(args,"-planet-economy-seconds");if(durationArg>=0)duration=Math.Max(900,int.Parse(args[durationArg+1]));report.measurement="Actual autonomous AI, "+duration+" simulation seconds; no wallet grants or CPU army mirror";output=args[Array.IndexOf(args,"-planet-output")+1];Directory.CreateDirectory(output);world=FindAnyObjectByType<PlanetDevelopment>();world.currentRtsContent=true;world.sessionMode=PlanetGameMode.AiTest;world.configuredRadius=120000;world.requestedCapacity=8192;world.ambientZombies=0;world.Paused=true;Application.targetFrameRate=-1;QualitySettings.vSyncCount=0;Application.logMessageReceived+=Log;}
        void Log(string message,string stack,LogType type){if(type==LogType.Exception||type==LogType.Error||type==LogType.Assert)report.runtimeErrors++;}
        void Check(bool value,string label){report.checks.Add((value?"PASS ":"FAIL ")+label);if(!value){report.status="FAIL";report.error+=label+"; ";}}
        IEnumerator Start(){double deadline=Time.realtimeSinceStartupAsDouble+120;while(!world.Ready&&Time.realtimeSinceStartupAsDouble<deadline)yield return null;if(!world.Ready){Check(false,"Session initialises");Finish();yield break;}
            Check(world.StrategyEnabled&&world.Base.Civilisation!=null,"Real autonomous strategy and settlement economy enabled");world.Base.Civilisation.Logistics.DeliveredForValidation=(team,resource,amount)=>{if(resource=="construction_materials")report.teams[team].deliveredMaterials+=amount;};report.width=Screen.width;report.height=Screen.height;firstTick=world.SimulationTicks;started=previous=Time.realtimeSinceStartupAsDouble;Time.captureDeltaTime=BattleSettings.Tick;world.Rig.InputEnabled=false;world.Paused=false;if(Array.IndexOf(Environment.GetCommandLineArgs(),"-planet-economy-eightfold")>=0){world.ChangeSimulationSpeed(1);world.ChangeSimulationSpeed(1);world.ChangeSimulationSpeed(1);report.measurement+="; 8x simulation with real GPU locomotion";}
            bool fast=Array.IndexOf(Environment.GetCommandLineArgs(),"-planet-economy-soak")>=0;uint manualTicks=0;if(fast){world.Paused=true;report.measurement="Strategic economy catch-up soak; actual cargo mission timing and infrastructure, no GPU locomotion or army advancement, no wallet grants";}
            while((fast?manualTicks:world.SimulationTicks-firstTick)<(uint)(duration*30)){if(fast){world.Base.Civilisation.Advance(8);while(world.Base.Civilisation.CatchingUp(world.definition.bodyId))world.Base.Civilisation.Advance(0);manualTicks+=240;if(manualTicks%1800==0)yield return null;}else yield return null;if(Array.IndexOf(Environment.GetCommandLineArgs(),"-planet-cargo-sync")>=0)world.Base.CargoNavigation.Step(0,true);double now=Time.realtimeSinceStartupAsDouble;uint ticks=fast?manualTicks:world.SimulationTicks-firstTick;if(ticks>900)frames.Add((now-previous)*1000);previous=now;
                double auditSeconds=(ticks-previousAuditTick)/30.0;previousAuditTick=ticks;if(ticks/108000>lastHour){lastHour=ticks/108000;File.WriteAllText(Path.Combine(output,"economy-state.json"),world.Base.Civilisation.Serialize());var line="seconds="+(ticks/30);for(int team=0;team<2;team++){var colony=world.Base.Settlements[team];line+=" team="+team+" buildings="+world.Base.Buildings.Count(b=>b.team==team&&!b.removed)+" pop="+colony.population+" food="+colony.foodSupplied+"/"+colony.foodDemand+" power="+colony.powerGeneration+"/"+colony.powerDemand+" households="+colony.households.Count+" housed="+colony.housedPopulation+"/"+colony.housingCapacity+" carts="+colony.cargoVehicles.Count+"/"+colony.cargoOrders.Count+" workforce="+colony.workforce+"/"+colony.plannedWorkerDemand+" mats="+colony.inventory.Get("construction_materials")+" storedFood="+colony.inventory.Get("food")+" grain="+colony.inventory.Get("grain")+" wheat="+world.Base.Buildings.Count(b=>b.team==team&&!b.removed&&b.definition.id=="civil_farm_wheat")+" seeds="+colony.inventory.Get("seeds")+" tech="+world.Base.Factions[team].technologies.Count+" orbitals="+world.Base.Civilisation.Orbitals.Assets(colony.body).Count+" plan="+world.Base.Civilisation.State.Faction(team).reason;}File.AppendAllText(Path.Combine(output,"hourly.txt"),line+Environment.NewLine);}
                for(int team=0;team<2;team++){if(duration>900&&ticks>=(uint)(duration*15)&&midpointBuildings[team]==0){midpointBuildings[team]=world.Base.Buildings.Count(b=>b.team==team&&!b.removed);midpointPopulation[team]=world.Base.Settlements[team].population;}var mines=world.Base.Buildings.Where(b=>b.team==team&&!b.removed&&b.definition.id=="mine"&&b.node>=0&&world.Base.Nodes[b.node].remaining>0).ToArray();report.teams[team].maximumMines=Math.Max(report.teams[team].maximumMines,mines.Length);
                    if(ticks>3600&&world.Base.Factions[team].wallet.Stock.materials<20)drought[team]+=auditSeconds;else drought[team]=0;report.teams[team].longestMaterialDrought=Math.Max(report.teams[team].longestMaterialDrought,drought[team]);
                    if(ticks>=15000&&!depleted[team]){depleted[team]=true;Check(mines.Length>=2,"Faction "+team+" expands extraction before depletion");if(mines.Length>0)world.Base.Nodes[mines[0].node].remaining=0;}
                }
            }
            world.Paused=true;double elapsed=Time.realtimeSinceStartupAsDouble-started;report.simulationHz=(fast?manualTicks:world.SimulationTicks-firstTick)/elapsed;report.units=world.unitCount;report.economySeconds=world.Base.Civilisation.SimulationTime;
            for(int team=0;team<2;team++){var hq=world.Base.Buildings.First(b=>b.team==team&&!b.removed&&b.definition.id=="command");var colony=world.Base.Settlements[team];var summary=report.teams[team];summary.endingMaterials=world.Base.Factions[team].wallet.Stock.materials;summary.buildings=world.Base.Buildings.Count(b=>b.team==team&&!b.removed);summary.cargo=colony.cargoVehicles.Count;
                summary.totalMines=world.Base.Buildings.Count(b=>b.team==team&&!b.removed&&b.definition.id=="mine");summary.connectedMines=world.Base.Buildings.Count(b=>b.team==team&&!b.removed&&b.Complete&&b.definition.id=="mine"&&b.node>=0&&world.Base.Nodes[b.node].remaining>0&&world.Base.Roads.Connected(b,hq));summary.recovered=summary.connectedMines>=2;
                summary.population=colony.population;summary.housing=colony.housingCapacity;summary.employed=colony.employed;summary.jobs=colony.workerDemand;
                if(duration>900){summary.midpointBuildings=midpointBuildings[team];summary.midpointPopulation=midpointPopulation[team];summary.outposts=world.Base.Buildings.Count(b=>b.team==team&&!b.removed&&b.definition.id=="outpost");summary.frontierDeposits=world.Base.Civilisation.Planet(world.definition.bodyId).frontierDeposits.Count;Check(summary.outposts==0,"Civilian growth does not place military forward bases");Check(summary.buildings>midpointBuildings[team],"Faction "+team+" continues constructing during the second half of a long run");Check(colony.population>midpointPopulation[team],"Faction "+team+" continues population growth beyond the initial settlement phase");}
                Check(colony.population>24,"Faction "+team+" grows its population through supplied housing");Check(colony.employed<=colony.population&&colony.employed<=colony.workerDemand,"Faction "+team+" staffing conserves available residents");
                summary.food=colony.inventory.Get("food");summary.seeds=colony.inventory.Get("seeds");summary.grain=colony.inventory.Get("grain");summary.foodDemand=colony.foodDemand;summary.foodSupplied=colony.foodSupplied;summary.technologies=world.Base.Factions[team].technologies.ToArray();summary.launchPads=world.Base.Buildings.Count(b=>b.team==team&&!b.removed&&b.definition.id=="civil_launch_pad");foreach(var asset in world.Base.Civilisation.Orbitals.Assets(colony.body))if(asset.faction==team){if(asset.kind==OrbitalPayloadKind.SurveySatellite)summary.satellites++;if(asset.kind==OrbitalPayloadKind.ResearchStation)summary.researchStations++;}
                if(Array.IndexOf(Environment.GetCommandLineArgs(),"-planet-growth-orbitals")>=0){Check(summary.satellites>0,"Faction "+team+" autonomously funds and launches a satellite");Check(summary.researchStations>0,"Faction "+team+" autonomously funds and launches an orbital research station");}
                summary.activity=world.Base.Civilisation.State.Faction(team).priority+": "+world.Base.Civilisation.State.Faction(team).reason;
                foreach(var b in world.Base.Buildings)if(b.team==team&&!b.removed){var item=colony.installations.Find(i=>i.id==b.persistentId);summary.installations.Add(b.definition.id+" complete="+b.Complete+" powered="+b.powered+" foodEff="+b.FoodEfficiency+" efficiency="+b.Efficiency+" food="+(item?.inventory.Get("food")??0)+" mats="+(item?.inventory.Get("construction_materials")??0)+" HQroad="+world.Base.Roads.Connected(b,hq)+" remaining="+(b.node>=0?world.Base.Nodes[b.node].remaining:0));}
                foreach(var vehicle in colony.cargoVehicles){summary.trucks.Add(vehicle.id+" "+vehicle.phase+" "+vehicle.resource+" arrived="+vehicle.gpuArrived+" version="+vehicle.navigationVersion+" distance="+vehicle.gpuRouteMetres+" loaded="+vehicle.loaded+" delivered="+vehicle.delivered+" departure="+vehicle.departure+" arrival="+vehicle.arrival);}
                Check(summary.totalMines>=3,"Faction "+team+" constructs multiple extractors and a paid replacement on another node");Check(summary.recovered,"Faction "+team+" retains two working HQ-road-connected mines after depletion");Check(summary.endingMaterials>=100&&summary.longestMaterialDrought<120,"Faction "+team+" maintains construction funds without prolonged material starvation");Check(summary.deliveredMaterials>100,"Faction "+team+" receives physical cargo deliveries of construction materials");
            }Check(report.runtimeErrors==0,"No runtime errors during autonomous growth");Finish();
        }
        void Finish(){if(world?.Base?.Civilisation!=null){report.dispatchFailureReuses=world.Base.Civilisation.Logistics.ReusedDispatchFailures;report.dispatchAuditRechecks=world.Base.Civilisation.Logistics.AuditedDispatchFailures;}SettlementPerformance.Write(output);Time.captureDeltaTime=0;frames.Sort();report.frameSamplesMs=frames.ToArray();if(frames.Count>0){report.medianMs=frames[frames.Count/2];report.p95Ms=frames[(int)((frames.Count-1)*.95)];}report.allocatedBytes=Profiler.GetTotalAllocatedMemoryLong();report.reservedBytes=Profiler.GetTotalReservedMemoryLong();File.WriteAllText(Path.Combine(output,"validation.json"),JsonUtility.ToJson(report,true));Application.Quit(report.status=="PASS"?0:1);}
        void OnDestroy(){Time.captureDeltaTime=0;Application.logMessageReceived-=Log;}
    }
}
